//! Differential tests: the synctv kernel against synctv-core @ 38970e0.
//!
//! Public upstream items are called through the `synctv-core` crate (linked from
//! `../upstream-src`). Private items (`member_role_policy.rs`, the kick-cooldown
//! validator and `validate_expiration`) are copied verbatim from the pinned commit by
//! `build.rs` and compiled here, with `crate::models`, `crate::Error`, `crate::Result` and
//! `Clock` resolving to synctv-core's own.
//!
//! Inputs are generated by a fixed-seed splitmix64; every run checks the same cases.
//! This is evidence of agreement on the tested inputs, not a proof of equivalence.

pub use synctv_core::{models, Error, Result};

pub mod service {
    pub mod room {
        pub mod member_role_policy {
            include!(concat!(env!("OUT_DIR"), "/member_role_policy.rs"));
        }
        pub mod member_kick {
            #[allow(unused_imports)]
            use crate::{Error, Result};
            include!(concat!(env!("OUT_DIR"), "/member_kick.rs"));
            pub fn validate(c: i64) -> Result<()> {
                validate_kick_cooldown_seconds(c)
            }
        }
        #[cfg(test)]
        mod policy_tests;
    }
    pub mod jwt {
        #[allow(unused_imports)]
        use crate::{Error, Result};
        use synctv_core::Clock;
        include!(concat!(env!("OUT_DIR"), "/jwt_expiration.rs"));
        pub fn validate(clock: &dyn Clock, exp: i64, leeway: u64) -> Result<()> {
            validate_expiration(clock, exp, leeway, "Token")
        }
    }
}

/// splitmix64.
pub struct Rng(pub u64);

impl Rng {
    pub fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
    pub fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
    pub fn bool(&mut self) -> bool {
        self.next() & 1 == 1
    }
    /// A u64 drawn from a mix of shapes: arbitrary, sparse, and masked subsets of
    /// the given bitspaces.
    pub fn bits(&mut self, masks: &[u64]) -> u64 {
        match self.below(6) {
            0 => self.next(),
            1 => 0,
            2 => 1u64 << self.below(64),
            3 => self.next() & self.next() & self.next(),
            _ => {
                let m = masks[self.below(masks.len() as u64) as usize];
                let extra = if self.below(4) == 0 { 1u64 << self.below(64) } else { 0 };
                (self.next() & m) | extra
            }
        }
    }
}

